/**
 * Thrown when new work is handed to a suspended member. Nothing is written
 * and nothing is published; the caller is expected to leave the issue as it was.
 */
export class MemberSuspendedError extends Error {
  readonly code = "conflict";

  constructor(message = "That member is suspended") {
    super(message);
    this.name = "MemberSuspendedError";
  }
}

type MemberStandingInput = {
  readonly orgId: OrgId;
  readonly memberId: MemberId;
};

/**
 * Shared guards for suspend and reinstate: tenant scope, a live membership,
 * `member:remove`, no self-service, and no acting on a role that outranks
 * the actor. A refusal throws before any write.
 */
async function requireStandingTarget(
  actor: Actor,
  input: MemberStandingInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = await memberRepo.findMemberById(input.orgId, input.memberId);
  if (member === null || isArchived(member)) {
    throw new NotFoundError("Member", input.memberId);
  }

  assertCan(actor, "member:remove", memberResource(member));

  if (actor.userId === member.userId) {
    throw new Error("You cannot suspend or reinstate yourself");
  }

  if (!hasRoleAtLeast(actor.role, member.role)) {
    throw new Error(
      `A ${actor.role} cannot suspend or reinstate a ${member.role}`,
    );
  }

  return member;
}

/**
 * Locks a member out without removing them. Role and seat stay; status
 * becomes `"suspended"`. Already-suspended members are returned unchanged
 * and publish nothing.
 */
export async function suspendMember(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
): Promise<Member> {
  const member = await requireStandingTarget(actor, input);
  if (member.status === "suspended") return member;

  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const updated = await memberRepo.updateMemberStatus(
    input.orgId,
    input.memberId,
    "suspended",
  );

  await emit("member.suspended", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    userId: updated.userId,
  });

  return updated;
}

/**
 * Restores a suspended member to `"active"`. An already-active member is
 * returned unchanged and publishes nothing.
 */
export async function reinstateMember(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
): Promise<Member> {
  const member = await requireStandingTarget(actor, input);
  if (member.status === "active") return member;

  const updated = await memberRepo.updateMemberStatus(
    input.orgId,
    input.memberId,
    "active",
  );

  await emit("member.reinstated", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    userId: updated.userId,
  });

  return updated;
}

