/** MemberSuspendedError lives in the service layer; detect it without importing that module into client bundles. */
function isMemberSuspendedError(
  error: unknown,
): error is Error & { readonly code: "conflict" } {
  return (
    error instanceof Error &&
    error.name === "MemberSuspendedError" &&
    "code" in error &&
    (error as { code?: unknown }).code === "conflict"
  );
}

/** True for the error classes this module knows how to translate faithfully. */
export function isDomainError(error: unknown): boolean {
  return (
    error instanceof PermissionDeniedError ||
    error instanceof TenantScopeError ||
    error instanceof FeatureDisabledError ||
    error instanceof AlreadyArchivedError ||
    error instanceof InvalidSlugError ||
    error instanceof ZodError ||
    isMemberSuspendedError(error)
  );
}

